        static byte[] ToAnsi(string text)
        {
            byte[] buf = new byte[text.Length + 1];
            for (int i = 0; i < text.Length; i++)
                buf[i] = (byte)text[i];
            return buf;
        }

        static byte[] ToUtf16(string text)
        {
            byte[] buf = new byte[(text.Length + 1) * 2];
            for (int i = 0; i < text.Length; i++) {
                buf[i * 2] = (byte)text[i];
                buf[i * 2 + 1] = (byte)((int)text[i] >> 8);
            }
            return buf;
        }

        static string FromAnsi(byte[] buf, int length)
        {
            if (length < 0) length = 0;
            if (length > buf.Length) length = buf.Length;
            char[] chars = new char[length];
            int n = 0;
            for (int i = 0; i < length; i++) {
                if (buf[i] == 0) break;
                chars[i] = (char)buf[i];
                n++;
            }
            return new string(chars, 0, n);
        }

        static string FromUtf16(byte[] buf, int byteLength)
        {
            if (byteLength < 0) byteLength = 0;
            if (byteLength > buf.Length) byteLength = buf.Length;
            int n = byteLength / 2;
            char[] chars = new char[n];
            for (int i = 0; i < n; i++)
                chars[i] = (char)(buf[i * 2] | (buf[i * 2 + 1] << 8));
            return new string(chars);
        }

